import csv,json,re,collections
r=list(csv.DictReader(open('A1/c1/part-3.store.tsv'),delimiter='\t'));inp={x['id']:x for x in csv.DictReader(open('A1/in/part-3.tsv'),delimiter='\t') if x['kind']=='system-closure-store-object'};rules=json.load(open('A1/c1/part-3.store.rules.json'));meta=json.load(open('A1/c1/part-3.store-research.json'));docs=json.load(open('A1/c1/part-3.store-docs.json'))
ruletext={
'documentation':'Only distinct outputs ending -man, -doc, or -info. S2.2-4 exempts their readable documentation content; this does not exempt the corresponding program.',
'binary-output':'Only distinct outputs ending -bin. The documented output convention places user-facing executables here. S2.2-9 requires those programs; S2.2-2 supplies the command-removal reasoning.',
'library-output':'Only distinct outputs ending -lib or -libgcc. These hold library code, executed by dependent programs without a separate confinement boundary. S2.2-10 and S2.2-2 require it.',
'documented-code-package':'An explicit source metadata or project-documentation match establishes executable/library functionality. Data-only packages are excluded. S2.2-9 covers commands and S2.2-10 covers libraries; removing the object removes that functionality. Bare store membership alone is not used.',
'service-unit':'Only generated unit definitions, excluding unit-script objects. Documentation establishes control of processes, sockets, devices, mounts, targets, timers and resources. Their effects extend to externally running processes and system resources; S2.2-1 and S2.2-2 apply rather than the single-program setting exemption.',
'restart-trigger':'Only X-Restart-Triggers objects generated by systemd-lib. Their documented source supplies change-sensitive restart inputs. These determine restarting external services, so S2.2-1 and S2.2-2 require them.',
'security-wrapper':'Only security-wrapper executable outputs. The wrapper source copies a compiled program into the privilege-wrapper directory and assigns configured rights. S2.2-9 and S2.2-15 require these executable privilege transitions.',
'pam-policy':'Only named PAM service policy objects. PAM reads these when privilege-granting applications authenticate or establish sessions. These account/access rules fall directly under S2.2-15, irrespective of storage location.',
'unit-script':'Only generated unit-script outputs. systemd-lib creates executable shell scripts for service lifecycle hooks. S2.2-10 requires this code running under the service shell’s rights.'}
quotes={
'https://nixos.org/manual/nixpkgs/stable/#multiple-output-file-type-groups':'is meant for user-facing binaries; is meant for libraries; is for user documentation; is for man pages; is for info pages',
'https://www.freedesktop.org/software/systemd/man/latest/systemd.unit.html':'A unit file is a plain text ini-style file that encodes information about a service',
'https://raw.githubusercontent.com/NixOS/nixpkgs/master/nixos/lib/systemd-lib.nix':'name = "unit-script-${scriptName}";',
'https://raw.githubusercontent.com/NixOS/nixpkgs/master/nixos/modules/security/wrappers/default.nix':'cp ${securityWrapper source}/bin/security-wrapper "$wrapperDir/${program}"',
'https://man7.org/linux/man-pages/man5/pam.conf.5.html':'When a PAM aware privilege granting application is started, it activates its attachment to the PAM-API.',
'https://gmplib.org/manual/Introduction-to-GMP':'GNU MP is a portable library written in C for arbitrary precision arithmetic',
'https://www.gnu.org/s/grub/':'GNU GRUB is a Multiboot boot loader.',
'https://www.gnu.org/software/libmicrohttpd/':'GNU libmicrohttpd is a small C library that makes it easy to run an HTTP server as part of another application.',
'https://man7.org/linux/man-pages/man5/sudoers.5.html':"The sudoers policy plugin determines a user's sudo privileges.",
'https://man.archlinux.org/man/resolvconf.conf.5.en':'The resolvconf.conf file is a shell script that is sourced by resolvconf(8)',
}
for v in docs.values():
 if v['quote']:quotes[v['url']]=' '.join(v['quote'].split())
# Each package source contributes only a short exact metadata quotation.
for v in meta.values():
 desc=' '.join(v.get('description','').split())
 if not desc or v['url'] in quotes:continue
 if desc.startswith('Boehm-'):desc='conservative garbage collector for C and C++'
 if '" +' in desc:desc=desc.split('" +')[0]
 quotes[v['url']]=' '.join(desc.split()[:24])
by=collections.defaultdict(list)
for x in r:
 if x['id'] in rules:by[rules[x['id']]].append(x)
text=['# Part 3 store-object classification notes','', 'Scope: 618 system-closure-store-object rows. Only the specified input, its raw files, the fixed text and public primary documentation were consulted. No object was removed. Store-closure membership and inventory category wording are not recording rules.','', '## Governing sentences','']
ss=open('SENTENCES.md').read().splitlines()
used=set(y for x in r for y in x['sentences'].split(','))
for line in ss:
 m=re.match(r'- \*\*(S[^*]+)\*\* (.*)',line)
 if m and m.group(1) in used:text.extend([m.group(1)+': '+m.group(2),''])
text+=['## Homogeneous rules and hand checks','', 'The following ten rows per rule were inspected against their inventory identities and the cited role documentation before the rule was accepted. The table records the checked fit; it is not a random mechanical existence check.','']
for rule,items in by.items():
 text.extend(['### '+rule,'',ruletext[rule],'','| Checked ID | Inspected identity | Why the rule fits |','|---|---|---|'])
 for x in items[:10]:
  n=inp[x['id']]['name'].split('-',1)[1]
  text.append('| '+x['id']+' | '+n+' | '+x['what_it_does']+' |')
 text.append('')
text+=['## Individual decisions and uncertainty','', 'All rows outside those rules were inspected individually. Known source definitions and activation references are used only when they identify the actual generated role. Where the inventory supplies only a store pathname, a general manual describes possible behavior but cannot reveal whether this artifact contains operative values, code, an empty configuration, or another generated form. Such cases remain UNKNOWN rather than receiving a decision guessed from the filename.','', 'The four HOLE cases are runtime databases. One reading exempts their contents as databases under S2.2-4; another treats the computations and decisions they enable as behavior under S2.2-1 and S2.2-2. The text does not specify how to distinguish unavailability of those contents from loss of the behavior calculated using them. This is a recording-boundary question, not a question about transferring accumulated program state.','', '| ID | Decision | Specific evidence limitation or determination |','|---|---|---|']
for x in r:
 if x['id'] not in rules:text.append('| '+x['id']+' | '+x['decision']+' | '+x['reason']+' |')
text+=['','## Primary documentation passages','', 'URLs identify program role or format. Public definitions establish roles, not exact reproduction of the installed binary. Package metadata excerpts below were fetched from the primary packaging repository. The raw inventory supplies the installed object identity.','']
for u,q in sorted(quotes.items()):text.extend(['- '+u,'  > '+q,''])
text+=['## Additional source observations','', '- https://raw.githubusercontent.com/NixOS/nixpkgs/master/nixos/lib/systemd-lib.nix generates restart inputs with `pkgs.writeText "X-Restart-Triggers-${name}"`.','- https://raw.githubusercontent.com/NixOS/nixpkgs/master/nixos/modules/system/activation/switchable-system.nix defines `pkgs.writers.writeJSON "switch-inhibitors" config.system.switch.inhibitors` and the constant `pkgs.writeText "empty-inhibitors" "{}"`. The constant is an operational comparison input, not a user document.','- https://raw.githubusercontent.com/NixOS/nixpkgs/master/nixos/modules/misc/documentation.nix defines `pkgs.writeShellScriptBin "nixos-help"`. The helper is executable even though it opens documentation.','- https://raw.githubusercontent.com/NixOS/nixpkgs/master/nixos/modules/services/networking/dhcpcd.nix defines `pkgs.writeShellScript "migrate-dhcpcd"` as a service pre-start command.','- A1/in/raw/nixos/activation-script.txt directly sources the mount and support scripts, executes the account-update and configuration-installation scripts, and consumes the account description and firmware path.','', '## Verification','', 'The final subset has 618 unique IDs, exactly matching the selected input kind. Every decision is allowed; the header and six-field shape are exact. Word limits were checked mechanically. Counts are provided in the subset result notification.']
open('A1/c1/part-3.store.notes.md','w').write('\n'.join(text)+'\n')
